export type Deadline = {
    remaining(): number;
    fits(ms: number): boolean;
};
export function startDeadline(totalMs: number, now?: () => number): Deadline;
export function callWithRetry<T>(spec: {
    effect: CallEffect;
    deadlineMs: number;
    maxAttempts?: number;
    now?: () => number;
    sleep?: (ms: number) => Promise<void>;
}, attempt: (timeoutMs: number) => Promise<AttemptResult<T>>): Promise<RetryResult<T>>;
